/**
 * Injeta mapStats nos objetos dos jogadores.
 * Chame após TEAMS estar carregado.
 */
function injectPlayerMapStats() {
  TEAMS.forEach(team => {
    team.players.forEach(player => {
      if (PLAYER_MAP_STATS[player.nick]) {
        player.mapStats = PLAYER_MAP_STATS[player.nick];
      }
    });
  });
  const real = Object.values(PLAYER_MAP_STATS).filter(s => !s._synthetic).length;
  const synth = Object.values(PLAYER_MAP_STATS).filter(s => s._synthetic).length;
  console.log(`✓ Map stats: ${real} real HLTV + ${synth} synthetic (${real + synth} total)`);
}

if (typeof document !== 'undefined') {
  document.addEventListener('DOMContentLoaded', () => {
    if (typeof TEAMS !== 'undefined') {
      injectPlayerMapStats();
    }
  });
}
